import {portableReplay,paintPortable} from './replay-sharing.js';
import {prepareReplay} from './replay-store.js';
const $=id=>document.getElementById(id),uid=()=>crypto.randomUUID(),blankCase=()=>({id:uid(),label:'新情境',from:0,to:5,moment:0,focus:'',question:'',feedback:'',reviewed:false,replay:null});
let doc,caseId,videoURL,db,dirty=false;
const request=indexedDB.open('courtiq-author',1);request.onupgradeneeded=()=>request.result.createObjectStore('drafts',{keyPath:'id'});request.onerror=()=>status('無法開啟本機草稿，仍可匯出備份');request.onsuccess=async()=>{db=request.result;await list();fresh();};
function status(s){$('status').textContent=s;}
function current(){return doc.scenarios.find(s=>s.id===caseId);}
function read(){for(const k of ['title','source','credit','category'])doc[k]=$(k).value;for(const k of ['label','focus','question','feedback'])current()[k]=$(k).value;for(const k of ['from','to','moment'])current()[k]=Number($(k).value);current().reviewed=$('reviewed').checked;}
function render(){stopPreview();for(const k of ['title','source','credit','category'])$(k).value=doc[k];$('scenarios').replaceChildren(...doc.scenarios.map(s=>new Option(s.label,s.id)));$('scenarios').value=caseId;for(const k of ['label','from','to','moment','focus','question','feedback'])$(k).value=current()[k];$('reviewed').checked=current().reviewed;$('captureInfo').textContent=current().replay?`已擷取 ${current().replay.steps} 步戰術`:'尚未擷取戰術';$('previewText').textContent='';renderReview();$('videoName').textContent=doc.videoName?`參考影片：${doc.videoName}（請選回檔案）`:'尚未選影片';$('versions').replaceChildren(...doc.versions.map(v=>{const b=document.createElement('button');b.textContent=new Date(v.at).toLocaleString();b.onclick=()=>{if(confirm('載回這個版本？未儲存修改會被取代。')){Object.assign(doc,structuredClone(v.data));caseId=doc.scenarios[0].id;render();dirty=true;}};return b;}));}
function fresh(){if(dirty&&!confirm('新增教材前請先儲存或匯出。放棄未儲存修改？'))return;doc={format:'courtiq-material-draft',schemaVersion:1,id:uid(),title:'未命名教材',source:'',credit:'',category:'',videoName:'',scenarios:[blankCase()],versions:[]};caseId=doc.scenarios[0].id;render();dirty=false;}
function all(){return new Promise((resolve,reject)=>{const r=db.transaction('drafts').objectStore('drafts').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function list(){const docs=await all();$('drafts').replaceChildren(new Option('選擇已儲存草稿',''),...docs.map(d=>new Option(d.title,d.id)));}
function validate(d){if(d?.format!=='courtiq-material-draft'||d.schemaVersion!==1||!Array.isArray(d.scenarios)||!d.scenarios.length||d.scenarios.length>20)throw Error('不支援的教材草稿');for(const s of d.scenarios){for(const k of ['from','to','moment'])if(!Number.isFinite(s[k])||s[k]<0)throw Error('片段時間無效');if(s.to<=s.from||s.moment<s.from||s.moment>s.to)throw Error('請確認片段起訖與觀察時刻');for(const k of ['label','focus','question','feedback'])if(typeof s[k]!=='string'||s[k].length>4000)throw Error('情境文字無效');if(s.replay)s.replay=prepareReplay(s.replay).record;}for(const k of ['title','source','credit','category','videoName'])if(typeof d[k]!=='string'||d[k].length>2000)throw Error('教材文字無效');if(new TextEncoder().encode(JSON.stringify(d)).length>2*1024*1024)throw Error('教材草稿最多 2 MB');return d;}
async function save(){try{read();validate(doc);if(!db)throw Error('本機儲存未就緒');const docs=await all();if(!docs.some(d=>d.id===doc.id)&&docs.length>=20)throw Error('最多 20 份草稿，請先匯出備份');const {versions,...data}=doc;const next={...doc,versions:[{at:new Date().toISOString(),data:structuredClone(data)},...versions].slice(0,5)};validate(next);await new Promise((resolve,reject)=>{const t=db.transaction('drafts','readwrite');t.objectStore('drafts').put(next);t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error);});doc=next;dirty=false;await list();render();status('已儲存本機版本；未發布到學生課程');}catch(e){status(e.message);}}
$('save').onclick=save;$('new').onclick=fresh;$('drafts').onchange=async()=>{const id=$('drafts').value;if(!id)return;if(dirty&&!confirm('放棄未儲存修改並開啟草稿？'))return;doc=(await all()).find(d=>d.id===id);caseId=doc.scenarios[0].id;render();dirty=false;};
$('addCase').onclick=()=>{read();if(doc.scenarios.length>=20)return status('每份最多 20 個情境');const s=blankCase();doc.scenarios.push(s);caseId=s.id;render();dirty=true;};$('scenarios').onchange=()=>{read();caseId=$('scenarios').value;render();};
$('videoFile').onchange=()=>{const f=$('videoFile').files[0];if(!f)return;if(videoURL)URL.revokeObjectURL(videoURL);videoURL=URL.createObjectURL(f);$('video').src=videoURL;doc.videoName=f.name;$('videoName').textContent=f.name;dirty=true;};
$('start').onclick=()=>{$('from').value=$('video').currentTime.toFixed(2);read();dirty=true;};$('end').onclick=()=>{$('to').value=$('video').currentTime.toFixed(2);read();dirty=true;};$('clip').onclick=()=>{read();try{validate(doc);if(!$('video').src)throw Error('請先選影片');$('video').currentTime=current().from;$('video').play().catch(e=>status(e.message));}catch(e){status(e.message);}};$('video').ontimeupdate=()=>{if(doc&&$('video').currentTime>=Number($('to').value))$('video').pause();};
let captureTarget=null,editorWindow=null,pendingReplay=null;
function openEditor(replay){read();captureTarget=caseId;pendingReplay=replay;if(editorWindow&&!editorWindow.closed){editorWindow.focus();if(replay)editorWindow.postMessage({type:'courtiq-author-restore',replay},location.origin);return;}editorWindow=window.open('./?authorBoard=1','courtiq-material-editor');if(!editorWindow)status('請允許開啟戰術板視窗後重試');else status('已開啟戰術板，完成後按「帶回教材室」');}
$('capture').onclick=()=>openEditor(null);$('restore').onclick=()=>openEditor(current().replay);
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==editorWindow)return;if(e.data?.type==='courtiq-author-ready'&&pendingReplay){editorWindow.postMessage({type:'courtiq-author-restore',replay:pendingReplay},location.origin);pendingReplay=null;}if(e.data?.type==='courtiq-author-result'){if(e.data.error)return status(e.data.error);try{const target=doc.scenarios.find(s=>s.id===captureTarget);if(!target)return;target.replay=prepareReplay(e.data.replay).record;target.reviewed=false;dirty=true;if(target.id===caseId){read();target.reviewed=false;render();}status('戰術已帶回本情境，請檢查後儲存版本');}catch(err){status(err.message);}}});
let previewData=null,playing=false,clock=0,raf=null;
function stopPreview(){playing=false;if(raf)cancelAnimationFrame(raf);raf=null;}
function paintPreview(t){if(!previewData)return;paintPortable($('replayCanvas'),previewData,t);$('replaySeek').value=t;$('replayTime').textContent=t.toFixed(1)+' / '+previewData.duration+' 秒';}
function renderReview(){const s=current();$('reviewSummary').textContent=s.label+'\n\n學習重點：'+(s.focus||'尚未提供')+'\n問題：'+(s.question||'尚未提供')+'\n解析：'+(s.feedback||'尚待確認');previewData=s.replay?portableReplay(s.replay):null;$('replayCanvas').hidden=!previewData;$('replayPlay').disabled=!previewData||!previewData.duration;$('replaySeek').disabled=!previewData;$('replaySeek').max=previewData?.duration||0;$('replayPlay').textContent='播放戰術';$('replayTime').textContent=previewData?'':'尚無戰術，可匯入已整理教材或選擇建立';if(previewData)paintPreview(0);}
$('replayPlay').onclick=()=>{if(playing){stopPreview();$('replayPlay').textContent='播放戰術';return;}let t=Number($('replaySeek').value);if(t>=previewData.duration)t=0;playing=true;clock=performance.now()-t*1000;$('replayPlay').textContent='暫停';function tick(now){const time=Math.min(previewData.duration,(now-clock)/1000);paintPreview(time);if(time>=previewData.duration){stopPreview();$('replayPlay').textContent='播放戰術';}else raf=requestAnimationFrame(tick);}raf=requestAnimationFrame(tick);};$('replaySeek').oninput=()=>{stopPreview();$('replayPlay').textContent='播放戰術';paintPreview(Number($('replaySeek').value));};
$('preview').onclick=()=>{read();stopPreview();renderReview();const s=current();$('previewText').textContent=`${s.label}\n影片 ${s.from}–${s.to} 秒，觀察 ${s.moment} 秒\n\n學習重點：${s.focus||'待填'}\n問題：${s.question||'待填'}\n解讀：${s.feedback||'待確認'}\n\n${s.reviewed?'教練已核對':'尚待教練核對'} · ${s.replay?s.replay.steps+' 步戰術':'尚無戰術'}`;};
$('export').onclick=()=>{try{read();validate(doc);const u=URL.createObjectURL(new Blob([JSON.stringify(doc)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='CourtIQ_Material_'+doc.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);status('已匯出教材草稿；不含影片，不能當作演練 JSON 匯入');}catch(e){status(e.message);}};$('import').onclick=()=>$('json').click();$('json').onchange=async()=>{try{const f=$('json').files[0];if(!f||f.size>2*1024*1024)throw Error('檔案最多 2 MB');const d=validate(JSON.parse(await f.text()));if(dirty&&!confirm('放棄未儲存修改並匯入？'))return;doc={...d,id:uid(),versions:[]};caseId=doc.scenarios[0].id;render();dirty=true;status('已匯入為新草稿，請儲存');}catch(e){status(e.message);}$('json').value='';};
document.addEventListener('input',e=>{if(e.target.closest('input,textarea'))dirty=true;});window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});

function fitText(){document.querySelectorAll('textarea').forEach(el=>{el.style.height='auto';el.style.height=Math.max(110,el.scrollHeight+4)+'px';});}document.addEventListener('input',fitText);document.querySelectorAll('details').forEach(d=>d.addEventListener('toggle',fitText));
